// Builds supabase/seed.sql from the current local content.
//
// Usage: node scripts/build-db-seed.mjs
// The generated file contains content only. It does not create auth users or
// admin_users rows; local test accounts are created by the DB test harness or
// by the operator in a local database.

import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');

const content = JSON.parse(
  await readFile(path.join(root, 'data', 'content.json'), 'utf8'),
);

let tag = 'ccafe';
while (content && JSON.stringify(content).includes(`$${tag}$`)) tag += '_';

const json = JSON.stringify(content);
const note = 'النسخة الحالية من data/content.json';

const sql = `-- Generated by scripts/build-db-seed.mjs from data/content.json.
-- Do not edit this file by hand; regenerate it instead.
-- This seed contains content only; it creates no auth users and no admins.

insert into public.site_content (id, version, content, saved_at)
values (1, 1, $${tag}$${json}$${tag}$::jsonb, now())
on conflict (id) do nothing;

insert into public.content_history (version, content, note, created_at)
values (1, $${tag}$${json}$${tag}$::jsonb, '${note}', now())
on conflict (version) do nothing;
`;

await writeFile(path.join(root, 'supabase', 'seed.sql'), sql, 'utf8');
console.log(`Wrote supabase/seed.sql (${Buffer.byteLength(sql, 'utf8')} bytes).`);
